using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using Por.Core;
class Halted:Exception{}
class TestIo:IGameIoHost{public string Message;public Queue<byte> Keys=new Queue<byte>();public List<string> Events=new List<string>();public bool Pending=false;public bool KeyPressed{get{return Pending&&Keys.Count>0;}}public byte ReadKey(){Events.Add("key");return Keys.Count>0?Keys.Dequeue():(byte)13;}public void SoundCommand(ushort c){Events.Add("sound:"+c);}public void SoundSuspend(){Events.Add("suspend");}public void Interrupt(byte n,Types.TInterruptRegisters r){Events.Add("int:"+n+":"+r.ax);}public void Halt(int c){throw new Halted();}public void WriteLine(string m){Message=m;}public TextWriter OpenDebugLog(string p){throw new NotSupportedException();}}
partial class Tests{
 static long checks;static Random rng=new Random(800397);static TestIo io=new TestIo();static string dir;static void Yes(bool v,string s){checks++;if(!v)throw new Exception(s);}static byte B(int x){return unchecked((byte)x);}static ushort W(int x){return unchecked((ushort)x);}static void Archive(string name,Dictionary<byte,byte[]> blocks){var packs=new List<byte[]>();foreach(var raw in blocks.Values){var p=new List<byte>();for(int a=0;a<raw.Length;a+=126){int n=Math.Min(126,raw.Length-a);p.Add((byte)(n-1));p.AddRange(raw.Skip(a).Take(n));}packs.Add(p.ToArray());}using(var b=new BinaryWriter(File.Create(Path.Combine(dir,name.ToLowerInvariant()+".dax")))){b.Write((ushort)(blocks.Count*9));int off=0,k=0;foreach(var row in blocks){b.Write(row.Key);b.Write(off);b.Write((ushort)row.Value.Length);b.Write((ushort)packs[k].Length);off+=packs[k++].Length;}foreach(var p in packs)b.Write(p);}DaxIo.ResetArchiveCache();}
 static byte[] Raw(int w,int h,int frames,Func<int,byte> fill){var bytes=new byte[17+w*h*frames*4];bytes[0]=B(h);bytes[1]=B(h>>8);bytes[2]=B(w);bytes[3]=B(w>>8);bytes[8]=B(frames);for(int n=0;n<8;n++)bytes[9+n]=B((n*2<<4)|(n*2+1));for(int n=17;n<bytes.Length;n++)bytes[n]=fill(n-17);return bytes;}
 static Types.TImgBuf Pic(int w,int h,int f,bool mask=false){Types.TImgBuf p=null;Blit.AllocPic(W(h),W(w),B(f),B(mask?1:0),ref p);return p;}
 static void VgaCold(){GDVars.video.cellShift=3;GDVars.video.screenShift=3;GDVars.video.maskShift=3;GDVars.video.keyed=true;GDVars.video.colours=16;GDVars.video.name="VGA";GDVars.video.ExpandFrames=(raw,off,m,c,p)=>{byte[] b=new byte[raw.Data.Length];for(int i=0;i<b.Length;i++)b[i]=unchecked((byte)raw[i]);PicVga.ExpandFrames(b,off,m,c,p);};GDVars.video.MirrorFrame=PicVga.MirrorFrame;GDVars.video.RemapColour=PicVga.RemapColour;}
 static void Main(string[] args){dir=Path.Combine(Path.GetTempPath(),"por-ten-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{GameIo.Host=io;GDVars.stingArg=false;GDVars.debugTraceEnabled=false;GDVars.gameDir=dir+Path.DirectorySeparatorChar;GDVars.virtualDisk=1;GDVars.dsSuppressingInsertDiskFlag=true;string name=args[0];var m=typeof(Tests).GetMethod("Run"+name,BindingFlags.Static|BindingFlags.NonPublic);if(m==null)throw new Exception("missing test "+name);try{m.Invoke(null,null);}catch(TargetInvocationException e){throw e.InnerException;}Console.WriteLine(name+" source-derived assertions: "+checks);}finally{DaxIo.ResetArchiveCache();Directory.Delete(dir,true);}}
}
